<?php\ndeclare(strict_types=1);\n\ntrait NotifiableTrait\n{\n    abstract protected function getApiKey(): string;\n    abstract protected function getRecipient(): string;\n    abstract protected function getMessage(): string;\n    abstract protected function getEndpoint(): string;\n\n    public function send(): bool\n    {\n        $headers = ['Content-Type' => 'application/json', 'Authorization' => 'Bearer ' . $this->getApiKey()];\n        $payload = json_encode(['recipient' => $this->getRecipient(), 'message' => $this->getMessage()]);\n        $ch = curl_init($this->getEndpoint());\n        curl_setopt_array($ch, [\n            CURLOPT_POST => true,\n            CURLOPT_POSTFIELDS => $payload,\n            CURLOPT_HTTPHEADER => $this->buildHeaders($headers),\n            CURLOPT_RETURNTRANSFER => true,\n            CURLOPT_TIMEOUT => 30\n        ]);\n        $response = curl_exec($ch);\n        if (curl_errno($ch)) {\n            throw new \RuntimeException('Send failed: ' . curl_error($ch));\n        }\n        curl_close($ch);\n        return json_decode($response, true);\n    }\n}\n